    def bands(n, is_separator):
        result = []
        start = 0
        for i in range(n):
            if is_separator(i):
                result.append((start, i))
                start = i + 1
        result.append((start, n))
        return result

    rows = bands(h, lambda r: all(v == grid[r][0] for v in grid[r]) and grid[r][0] == 0)
    cols = bands(w, lambda c: all(grid[r][c] == 0 for r in range(h)))

    # The non-background color is the scattered marker; separators are zero.
    counts = {}
    for row in grid:
        for v in row:
            if v != 0:
                counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    marker = next(v for v in counts if v != background)

    out = []
    for r0, r1 in rows:
        outrow = []
        for c0, c1 in cols:
            n = sum(grid[r][c] == marker
                    for r in range(r0, r1)
                    for c in range(c0, c1))
            outrow.append(1 if n == 2 else background)
        out.append(outrow)
    return out
