def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_colors = set()
    for r in range(h):
        if len(set(grid[r])) == 1:
            sep_colors.add(grid[r][0])
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1:
            sep_colors.update(vals)
    sep = max(sep_colors, key=lambda x: sum(v == x for row in grid for v in row))

    def get_bands(n, separator):
        bands = []
        start = 0
        for i in range(n):
            if separator(i):
                bands.append((start, i))
                start = i + 1
        bands.append((start, n))
        return bands

    rows = get_bands(h, lambda r: all(v == sep for v in grid[r]))
    cols = get_bands(w, lambda c: all(grid[r][c] == sep for r in range(h)))

    freq = {}
    for row in grid:
        for v in row:
            if v != sep:
                freq[v] = freq.get(v, 0) + 1
    background = max(freq, key=freq.get)
    marker = min((v for v in freq if v != background), key=lambda v: freq[v])

    return [[1 if sum(grid[r][c] == marker
                      for r in range(r0, r1)
                      for c in range(c0, c1)) == 2 else background
             for c0, c1 in cols]
            for r0, r1 in rows]
